const body = $json.body || $json;
const headers = $json.headers || {};
const query = $json.query || {};
const params = $json.params || {};

const customData = body.customData || body.custom_data || {};
const location = body.location || {};
const workflow = body.workflow || {};
const user = body.user || {};

function pick(...values) {
  return values.find(value => value !== undefined && value !== null && value !== '') || null;
}

function pickObject(...values) {
  return values.find(value => value && typeof value === 'object' && !Array.isArray(value)) || {};
}

function cleanUrlValue(value) {
  if (value === undefined || value === null) return null;

  const text = String(value).trim();

  return text || null;
}

function getUrlParam(urls, aliases) {
  const aliasSet = new Set(
    aliases.map(alias => String(alias).trim().toLowerCase())
  );

  function safeDecode(value) {
    const text = String(value ?? '').replace(/\+/g, ' ');

    try {
      return decodeURIComponent(text);
    } catch (error) {
      return text;
    }
  }

  for (const rawUrl of urls) {
    const cleanedUrl = typeof cleanUrlValue === 'function'
      ? cleanUrlValue(rawUrl)
      : cleanText(rawUrl);

    if (!cleanedUrl) continue;

    // Parser manual para funcionar no sandbox do Code node do n8n,
    // sem depender das classes globais URL ou URLSearchParams.
    let queryString = String(cleanedUrl).replace(/&amp;/gi, '&');

    const questionMarkIndex = queryString.indexOf('?');

    if (questionMarkIndex >= 0) {
      queryString = queryString.slice(questionMarkIndex + 1);
    }

    const hashIndex = queryString.indexOf('#');

    if (hashIndex >= 0) {
      queryString = queryString.slice(0, hashIndex);
    }

    for (const pair of queryString.split('&')) {
      if (!pair) continue;

      const equalsIndex = pair.indexOf('=');

      const rawKey = equalsIndex >= 0
        ? pair.slice(0, equalsIndex)
        : pair;

      const rawValue = equalsIndex >= 0
        ? pair.slice(equalsIndex + 1)
        : '';

      const key = safeDecode(rawKey).trim().toLowerCase();

      if (!aliasSet.has(key)) continue;

      const decodedValue = safeDecode(rawValue);

      const cleanedValue = typeof cleanUrlValue === 'function'
        ? cleanUrlValue(decodedValue)
        : cleanText(decodedValue);

      if (cleanedValue) return cleanedValue;
    }
  }

  return null;
}

const contact = body.contact || {};
const attributionSource = pickObject(
  contact.attributionSource,
  contact.attribution_source,
  body.attributionSource,
  body.attribution_source,
  customData.attributionSource,
  customData.attribution_source
);
const lastAttributionSource = pickObject(
  contact.lastAttributionSource,
  contact.last_attribution_source,
  body.lastAttributionSource,
  body.last_attribution_source,
  customData.lastAttributionSource,
  customData.last_attribution_source
);

const attributionUrls = [
  attributionSource.url,
  attributionSource.sourceUrl,
  attributionSource.source_url,
  lastAttributionSource.url,
  lastAttributionSource.sourceUrl,
  lastAttributionSource.source_url,
  body.sourceUrl,
  body.source_url,
  body.source?.url,
  customData.sourceUrl,
  customData.source_url
];

const googleCampaignIdFromUrl = getUrlParam(
  attributionUrls,
  ['campaignid', 'campaign_id', 'campaignId']
);

const googleAdgroupIdFromUrl = getUrlParam(
  attributionUrls,
  ['adgroupid', 'ad_group_id', 'adgroup_id', 'adGroupId']
);

const googleAdIdFromUrl = getUrlParam(
  attributionUrls,
  ['adid', 'ad_id', 'creative', 'creative_id']
);

const fbclidFromUrl = getUrlParam(attributionUrls, ['fbclid']);
const gclidFromUrl = getUrlParam(attributionUrls, ['gclid']);
const gbraidFromUrl = getUrlParam(attributionUrls, ['gbraid']);
const wbraidFromUrl = getUrlParam(attributionUrls, ['wbraid']);

function normalizePhone(phone) {
  if (!phone) return null;
  return String(phone).replace(/\D/g, '');
}

function deepClone(obj) {
  return JSON.parse(JSON.stringify(obj || {}));
}

function normalizeText(value) {
  if (!value) return null;

  return String(value)
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, '_')
    .replace(/-/g, '_')
    .toLowerCase();
}

function normalizeEventCode(value) {
  const normalized = normalizeText(value);

  const map = {
    lead: 'lead',

    primeira: 'primeira_conversa',
    primeira_conversa: 'primeira_conversa',
    primeira_conversa_realizada: 'primeira_conversa',
    primeira_abordagem: 'primeira_conversa',

    agendado: 'agendado',
    avaliacao: 'agendado',
    avaliação: 'agendado',

    ganho: 'ganho',
    won: 'ganho',
    fechado: 'ganho',
    venda: 'ganho',

    perdido: 'perdido',
    lost: 'perdido',
    perda: 'perdido'
  };

  return map[normalized] || normalized || 'raw_event';
}

function normalizeStatus(eventCode, rawStatus) {
  if (eventCode === 'ganho') return 'won';
  if (eventCode === 'perdido') return 'lost';
  if (eventCode === 'primeira_conversa') return 'open';
  if (eventCode === 'agendado') return 'open';
  if (eventCode === 'lead') return pick(rawStatus, 'open');

  return rawStatus || null;
}

function redactSensitiveFields(obj) {
  const sensitiveKeys = [
    'meta_token',
    'access_token',
    'token',
    'api_key',
    'api_secret',
    'ga4_api_secret',
    'password',
    'secret',
    'authorization',
    'developer_token',
    'refresh_token'
  ];

  if (Array.isArray(obj)) {
    return obj.map(redactSensitiveFields);
  }

  if (obj && typeof obj === 'object') {
    const clean = {};

    for (const [key, value] of Object.entries(obj)) {
      const normalizedKey = key.toLowerCase();

      if (sensitiveKeys.some(sensitive => normalizedKey.includes(sensitive))) {
        clean[key] = '[REDACTED]';
      } else {
        clean[key] = redactSensitiveFields(value);
      }
    }

    return clean;
  }

  return obj;
}

const sanitizedBody = redactSensitiveFields(deepClone(body));
const sanitizedHeaders = redactSensitiveFields(deepClone(headers));

const sourceSystem = pick(
  body.source_system,
  customData.source_system,
  'ghl'
);

const rawEventName = pick(
  customData.nome_evento_crm,
  body.nome_evento_crm,
  body.event_type,
  body.eventType,
  body.type,
  body.event,
  'raw_event'
);

const eventCode = normalizeEventCode(rawEventName);

const locationId = pick(
  body.location_id,
  body.locationId,
  body.ghl_location_id,
  customData.location_id,
  customData.locationId,
  customData.ghl_location_id,
  location.id
);

const locationName = pick(
  body.location_name,
  body.locationName,
  customData.location_name,
  customData.locationName,
  location.name
);

/**
 * DECISÃO DO MODELO:
 * contact_id é a chave principal da jornada.
 * Não usamos body.id como fallback de contact_id,
 * porque nos eventos de oportunidade o body.id pode ser opportunity_id.
 */
const contactId = pick(
  customData.contact_id,
  customData.contactId,
  body.contact_id,
  body.contactId,
  body.contact?.id
);

/**
 * opportunity_id é complementar.
 * Pode usar body.id, mas não entra como contact_id.
 */
const opportunityId = pick(
  body.opportunity_id,
  body.opportunityId,
  body.opportunity?.id,
  customData.opportunity_id,
  customData.opportunityId,
  body.id
);

const pipelineId = pick(
  body.pipeline_id,
  body.pipelineId,
  body.opportunity?.pipeline_id,
  body.opportunity?.pipelineId,
  customData.pipeline_id,
  customData.pipelineId
);

const pipelineName = pick(
  body.pipeline_name,
  body.pipelineName,
  body.opportunity?.pipeline_name,
  body.opportunity?.pipelineName,
  customData.pipeline_name,
  customData.pipelineName
);

const pipelineStage = pick(
  body.pipeline_stage,
  body.pipleline_stage,
  body.pipelineStage,
  body.opportunity?.pipeline_stage,
  body.opportunity?.pipleline_stage,
  body.opportunity?.pipelineStage,
  customData.pipeline_stage,
  customData.pipleline_stage,
  customData.pipelineStage
);

const rawStatus = pick(
  body.status,
  body.opportunity?.status,
  customData.status
);

const status = normalizeStatus(eventCode, rawStatus);

const phoneRaw = pick(
  body.phone,
  body.phone_number,
  body.phoneNumber,
  body.phone_raw,
  customData.phone_raw,
  customData.phone,
  customData.phone_number,
  body.contact?.phone,
  body.contact?.phone_number,
  body.contact?.phoneNumber
);

const email = pick(
  body.email,
  body.email_address,
  body.emailAddress,
  customData.email,
  customData.email_address,
  body.contact?.email
);

const normalizedPhone = normalizePhone(phoneRaw);

const firstName = pick(
  body.first_name,
  body.firstName,
  customData.first_name,
  customData.firstName,
  body.contact?.first_name,
  body.contact?.firstName
);

const lastName = pick(
  body.last_name,
  body.lastName,
  customData.last_name,
  customData.lastName,
  body.contact?.last_name,
  body.contact?.lastName
);

const fullName = pick(
  body.full_name,
  body.fullName,
  customData.full_name,
  customData.fullName,
  body.contact?.full_name,
  body.contact?.fullName
);

const valorGanho = pick(
  customData.valor_ganho,
  customData.closed_value,
  customData.value,
  body.valor_ganho,
  body.closed_value,
  body.value,
  body.monetary_value,
  body.monetaryValue,
  body.opportunity?.monetary_value,
  body.opportunity?.monetaryValue
);

const formaGanho = pick(
  customData.forma_ganho,
  customData.forma_pagamento_ganho,
  customData.payment_method,
  customData.forma_pagamento,
  body.forma_ganho,
  body.forma_pagamento_ganho,
  body.payment_method,
  body.forma_pagamento
);

const produtoServico = pick(
  customData.produto_servico,
  customData.produto_serviço,
  customData.produto_servico_ganho,
  customData.produto_serviço_ganho,
  customData['produto/serviço_ganho'],
  customData['produto/servico_ganho'],
  customData.product_service,
  customData.service_product,

  body.produto_servico,
  body.produto_serviço,
  body.produto_servico_ganho,
  body.produto_serviço_ganho,
  body['produto/serviço_ganho'],
  body['produto/servico_ganho'],
  body.product_service,
  body.service_product,

  // fallback legado
  customData.procedimento_ganho,
  customData.procedimento_fechado,
  customData.procedure_closed,
  customData.procedimento,
  body.procedimento_ganho,
  body.procedimento_fechado,
  body.procedure_closed,
  body.procedimento
);

const categoriaProdutoServico = pick(
  customData.categoria_produto_servico,
  customData.categoria_produto_serviço,
  customData.categoria_ganho,
  customData.categoria,
  customData.product_category,
  customData.service_category,

  body.categoria_produto_servico,
  body.categoria_produto_serviço,
  body.categoria_ganho,
  body.categoria,
  body.product_category,
  body.service_category
);

const procedimentoGanho = pick(
  customData.procedimento_ganho,
  customData.procedimento_fechado,
  customData.procedure_closed,
  customData.procedimento,
  body.procedimento_ganho,
  body.procedimento_fechado,
  body.procedure_closed,
  body.procedimento,

  // fallback novo para compatibilidade com dashboards/queries antigos
  produtoServico
);

const motivoPerdaCategoria = pick(
  customData.motivo_perda_categoria,
  customData.loss_reason_category,
  body.motivo_perda_categoria,
  body.loss_reason_category
);

const motivoPerdaDetalhe = pick(
  customData.motivo_perda_detalhe,
  customData.loss_reason,
  body.motivo_perda_detalhe,
  body.loss_reason
);

const normalized = {
  source_system: sourceSystem,

  event_type: eventCode,
  event_code: eventCode,
  event_name: rawEventName,

  location_id: locationId,
  ghl_location_id: locationId,
  location_name: locationName,

  contact_id: contactId,
  opportunity_id: opportunityId,

  pipeline_id: pipelineId,
  pipeline_name: pipelineName,
  pipeline_stage: pipelineStage,
  status,

  phone: normalizedPhone,
  phone_raw: phoneRaw,
  email,

  full_name: fullName,
  first_name: firstName,
  last_name: lastName,
  tags: body.tags || null,
  contact_type: body.contact_type || body.contactType || null,
  date_created: body.date_created || body.dateCreated || null,

  lead_origem: pick(body.lead_origem, customData.lead_origem),
  lead_entrada: pick(body.lead_entrada, customData.lead_entrada),
  lead_agencias: pick(body.lead_agencias, customData.lead_agencias),

  utm_source: pick(
    body.utm_source,
    body.utmSource,
    customData.utm_source,
    customData.utmSource,
    attributionSource.utmSource,
    attributionSource.utm_source,
    lastAttributionSource.utmSource,
    lastAttributionSource.utm_source,
    getUrlParam(attributionUrls, ['utm_source'])
  ),
  utm_medium: pick(
    body.utm_medium,
    body.utmMedium,
    customData.utm_medium,
    customData.utmMedium,
    attributionSource.utmMedium,
    attributionSource.utm_medium,
    lastAttributionSource.utmMedium,
    lastAttributionSource.utm_medium,
    getUrlParam(attributionUrls, ['utm_medium'])
  ),
  utm_campaign: pick(
    body.utm_campaign,
    body.utmCampaign,
    customData.utm_campaign,
    customData.utmCampaign,
    attributionSource.campaign,
    attributionSource.utmCampaign,
    attributionSource.utm_campaign,
    lastAttributionSource.campaign,
    lastAttributionSource.utmCampaign,
    lastAttributionSource.utm_campaign,
    getUrlParam(attributionUrls, ['utm_campaign'])
  ),
  utm_content: pick(
    body.utm_content,
    body.utmContent,
    customData.utm_content,
    customData.utmContent,
    attributionSource.utmContent,
    attributionSource.utm_content,
    lastAttributionSource.utmContent,
    lastAttributionSource.utm_content,
    getUrlParam(attributionUrls, ['utm_content'])
  ),
  utm_term: pick(
    body.utm_term,
    body.utmTerm,
    customData.utm_term,
    customData.utmTerm,
    attributionSource.utmTerm,
    attributionSource.utm_term,
    lastAttributionSource.utmTerm,
    lastAttributionSource.utm_term,
    getUrlParam(attributionUrls, ['utm_term'])
  ),

  conversion_source: pick(body.conversionSource, customData.conversionSource),
  entry_point_conversion_source: pick(body.entryPointConversionSource, customData.entryPointConversionSource),
  entry_point_conversion_app: pick(body.entryPointConversionApp, customData.entryPointConversionApp),

  source_type: pick(
    body.sourceType,
    customData.sourceType,
    attributionSource.sourceType,
    attributionSource.source_type,
    attributionSource.type,
    lastAttributionSource.sourceType,
    lastAttributionSource.source_type,
    lastAttributionSource.type
  ),

  // Meta Lead Ads attribution fix:
  // for native forms, GHL often sends customData.sourceId empty on the lead event,
  // but contact.attributionSource.adId is already available.
  // Keep customData/sourceId as final fallback for legacy flows.
  source_id: pick(
    attributionSource.adId,
    attributionSource.ad_id,
    attributionSource.adID,
    lastAttributionSource.adId,
    lastAttributionSource.ad_id,
    lastAttributionSource.adID,
    body.sourceId,
    customData.sourceId
  ),

  source_url: pick(
    body.sourceUrl,
    customData.sourceUrl,
    body.source?.url,
    attributionSource.url,
    attributionSource.sourceUrl,
    attributionSource.source_url,
    lastAttributionSource.url,
    lastAttributionSource.sourceUrl,
    lastAttributionSource.source_url
  ),
  source_ads: pick(body.sourceAds, customData.sourceAds),

  meta_attribution: {
    attribution_source_ad_id: pick(attributionSource.adId, attributionSource.ad_id, attributionSource.adID),
    last_attribution_source_ad_id: pick(lastAttributionSource.adId, lastAttributionSource.ad_id, lastAttributionSource.adID),
    attribution_source_adset_id: pick(attributionSource.adSetId, attributionSource.adsetId, attributionSource.ad_set_id, attributionSource.adset_id),
    last_attribution_source_adset_id: pick(lastAttributionSource.adSetId, lastAttributionSource.adsetId, lastAttributionSource.ad_set_id, lastAttributionSource.adset_id),
    attribution_source_campaign_id: pick(attributionSource.campaignId, attributionSource.campaign_id),
    last_attribution_source_campaign_id: pick(lastAttributionSource.campaignId, lastAttributionSource.campaign_id)
  },

  ctwa_clid: pick(body.ctwaClid, customData.ctwaClid),
  ctwa_payload: pick(body.ctwaPayload, body.ctwapayload, customData.ctwaPayload, customData.ctwapayload),

  fbp: pick(body.fbp, customData.fbp),
  fbc: pick(body.fbc, customData.fbc),
  fbclid: pick(
    body.fbclid,
    customData.fbclid,
    attributionSource.fbclid,
    lastAttributionSource.fbclid,
    fbclidFromUrl
  ),
  gclid: pick(
    body.gclid,
    body.google_click_id,
    body.googleClickId,
    body['Google Click ID'],
    customData.gclid,
    customData.google_click_id,
    customData.googleClickId,
    customData['Google Click ID'],
    attributionSource.gclid,
    lastAttributionSource.gclid,
    gclidFromUrl
  ),
  gbraid: pick(
    body.gbraid,
    customData.gbraid,
    attributionSource.gbraid,
    lastAttributionSource.gbraid,
    gbraidFromUrl
  ),
  wbraid: pick(
    body.wbraid,
    customData.wbraid,
    attributionSource.wbraid,
    lastAttributionSource.wbraid,
    wbraidFromUrl
  ),

  // Google Ads ValueTrack:
  // campos explícitos primeiro; URL de atribuição do GHL como fallback seguro.
  google_campaign_id: pick(
    body.google_campaign_id,
    body.googleCampaignId,
    body.campaignid,
    body.campaign_id,
    customData.google_campaign_id,
    customData.googleCampaignId,
    customData.campaignid,
    customData.campaign_id,
    attributionSource.campaignId,
    attributionSource.campaign_id,
    lastAttributionSource.campaignId,
    lastAttributionSource.campaign_id,
    googleCampaignIdFromUrl
  ),
  google_adgroup_id: pick(
    body.google_adgroup_id,
    body.googleAdgroupId,
    body.adgroupid,
    body.adgroup_id,
    customData.google_adgroup_id,
    customData.googleAdgroupId,
    customData.adgroupid,
    customData.adgroup_id,
    attributionSource.adGroupId,
    attributionSource.adgroupId,
    attributionSource.ad_group_id,
    lastAttributionSource.adGroupId,
    lastAttributionSource.adgroupId,
    lastAttributionSource.ad_group_id,
    googleAdgroupIdFromUrl
  ),
  google_ad_id: pick(
    body.google_ad_id,
    body.googleAdId,
    body.adid,
    body.ad_id,
    body.creative,
    body.creative_id,
    customData.google_ad_id,
    customData.googleAdId,
    customData.adid,
    customData.ad_id,
    customData.creative,
    customData.creative_id,
    attributionSource.adId,
    attributionSource.ad_id,
    lastAttributionSource.adId,
    lastAttributionSource.ad_id,
    googleAdIdFromUrl
  ),
  google_keyword: pick(
    body.google_keyword,
    body.googleKeyword,
    body.keyword,
    customData.google_keyword,
    customData.googleKeyword,
    customData.keyword
  ),

  valor_ganho: valorGanho,
  forma_ganho: formaGanho,
  produto_servico: produtoServico,
  categoria_produto_servico: categoriaProdutoServico,

  // legado: manter temporariamente para compatibilidade
  procedimento_ganho: procedimentoGanho,

  motivo_perda_categoria: motivoPerdaCategoria,
  motivo_perda_detalhe: motivoPerdaDetalhe,

  workflow_id: workflow.id || null,
  workflow_name: workflow.name || null,

  assigned_user_first_name: user.firstName || null,
  assigned_user_last_name: user.lastName || null,
  assigned_user_email: user.email || null
};

return [
  {
    json: {
      received_at: new Date().toISOString(),

      source_system: sourceSystem,
      event_type: eventCode,

      location_id: locationId,
      location_name: locationName,

      contact_id: contactId,
      phone: normalizedPhone,
      email,

      request_method: $json.method || 'POST',
      request_path: $json.path || '/webhook/inbound-events',
      request_headers: sanitizedHeaders,
      request_query: query,
      request_body: sanitizedBody,

      payload: {
        body: sanitizedBody,
        headers: sanitizedHeaders,
        query,
        params,
        normalized
      }
    }
  }
];

const row = $json;
const payload = row.payload || {};
const normalized = payload.normalized || {};
const rawBody = payload.body || {};
const rawCustomData = rawBody.customData || rawBody.custom_data || {};
const rawContact = rawBody.contact || {};

function pick(...values) {
  return values.find(value => value !== undefined && value !== null && value !== '') || null;
}

function pickObject(...values) {
  return values.find(value => value && typeof value === 'object' && !Array.isArray(value)) || {};
}

const attributionSource = pickObject(
  rawContact.attributionSource,
  rawContact.attribution_source,
  rawBody.attributionSource,
  rawBody.attribution_source,
  rawCustomData.attributionSource,
  rawCustomData.attribution_source
);
const lastAttributionSource = pickObject(
  rawContact.lastAttributionSource,
  rawContact.last_attribution_source,
  rawBody.lastAttributionSource,
  rawBody.last_attribution_source,
  rawCustomData.lastAttributionSource,
  rawCustomData.last_attribution_source
);

function cleanText(value) {
  if (value === undefined || value === null) return null;

  const text = String(value).trim();

  const invalidValues = [
    '',
    'null',
    'undefined',
    'nao identificado',
    'não identificado',
    'nao_identificado',
    'não_identificado',
    'n/a',
    'sem informação',
    'sem informacao'
  ];

  if (invalidValues.includes(text.toLowerCase())) {
    return null;
  }

  return text;
}


function getUrlParam(urls, aliases) {
  const aliasSet = new Set(
    aliases.map(alias => String(alias).trim().toLowerCase())
  );

  function safeDecode(value) {
    const text = String(value ?? '').replace(/\+/g, ' ');

    try {
      return decodeURIComponent(text);
    } catch (error) {
      return text;
    }
  }

  for (const rawUrl of urls) {
    const cleanedUrl = typeof cleanUrlValue === 'function'
      ? cleanUrlValue(rawUrl)
      : cleanText(rawUrl);

    if (!cleanedUrl) continue;

    // Parser manual para funcionar no sandbox do Code node do n8n,
    // sem depender das classes globais URL ou URLSearchParams.
    let queryString = String(cleanedUrl).replace(/&amp;/gi, '&');

    const questionMarkIndex = queryString.indexOf('?');

    if (questionMarkIndex >= 0) {
      queryString = queryString.slice(questionMarkIndex + 1);
    }

    const hashIndex = queryString.indexOf('#');

    if (hashIndex >= 0) {
