function getUrlParam(urls, aliases) {
  const aliasSet = new Set(
    aliases.map(alias => String(alias).trim().toLowerCase())
  );

  function safeDecode(value) {
    const text = String(value ?? '').replace(/\+/g, ' ');

    try {
      return decodeURIComponent(text);
    } catch (error) {
      return text;
    }
  }

  for (const rawUrl of urls) {
    const cleanedUrl = typeof cleanUrlValue === 'function'
      ? cleanUrlValue(rawUrl)
      : cleanText(rawUrl);

    if (!cleanedUrl) continue;

    // Parser manual para funcionar no sandbox do Code node do n8n,
    // sem depender das classes globais URL ou URLSearchParams.
    let queryString = String(cleanedUrl).replace(/&amp;/gi, '&');

    const questionMarkIndex = queryString.indexOf('?');

    if (questionMarkIndex >= 0) {
      queryString = queryString.slice(questionMarkIndex + 1);
    }

    const hashIndex = queryString.indexOf('#');

    if (hashIndex >= 0) {
      queryString = queryString.slice(0, hashIndex);
    }

    for (const pair of queryString.split('&')) {
      if (!pair) continue;

      const equalsIndex = pair.indexOf('=');

      const rawKey = equalsIndex >= 0
        ? pair.slice(0, equalsIndex)
        : pair;

      const rawValue = equalsIndex >= 0
        ? pair.slice(equalsIndex + 1)
        : '';

      const key = safeDecode(rawKey).trim().toLowerCase();

      if (!aliasSet.has(key)) continue;

      const decodedValue = safeDecode(rawValue);

      const cleanedValue = typeof cleanUrlValue === 'function'
        ? cleanUrlValue(decodedValue)
        : cleanText(decodedValue);

      if (cleanedValue) return cleanedValue;
    }
  }

  return null;
}

