  rawCustomData.campaign_id,
  attributionSource.campaignId,
  attributionSource.campaign_id,
  lastAttributionSource.campaignId,
  lastAttributionSource.campaign_id,
  googleCampaignIdFromUrl
));
const googleAdgroupId = cleanText(pick(
  normalizedEvent.google_adgroup_id,
  rawBody.google_adgroup_id,
  rawBody.googleAdgroupId,
  rawBody.adgroupid,
  rawBody.adgroup_id,
  rawCustomData.google_adgroup_id,
  rawCustomData.googleAdgroupId,
  rawCustomData.adgroupid,
  rawCustomData.adgroup_id,
  attributionSource.adGroupId,
  attributionSource.adgroupId,
  attributionSource.ad_group_id,
  lastAttributionSource.adGroupId,
  lastAttributionSource.adgroupId,
  lastAttributionSource.ad_group_id,
  googleAdgroupIdFromUrl
));
const googleAdId = cleanText(pick(
  normalizedEvent.google_ad_id,
  rawBody.google_ad_id,
  rawBody.googleAdId,
  rawBody.adid,
  rawBody.ad_id,
  rawBody.creative,
  rawBody.creative_id,
  rawCustomData.google_ad_id,
  rawCustomData.googleAdId,
  rawCustomData.adid,
  rawCustomData.ad_id,
  rawCustomData.creative,
  rawCustomData.creative_id,
  attributionSource.adId,
  attributionSource.ad_id,
  lastAttributionSource.adId,
  lastAttributionSource.ad_id,
  googleAdIdFromUrl
));
const googleKeyword = cleanText(pick(
  normalizedEvent.google_keyword,
  rawBody.google_keyword,
  rawBody.googleKeyword,
  rawBody.keyword,
  rawCustomData.google_keyword,
  rawCustomData.googleKeyword,
  rawCustomData.keyword
));

const hasGoogleTrackingSignal = Boolean(
  gclid || gbraid || wbraid || googleCampaignId || googleAdgroupId || googleAdId || googleKeyword
);

// Inferência segura para Google Ads: quando o GHL não preencher lead_origem/lead_entrada,
// mas o payload trouxer IDs Google, tratamos como Google Ads / Form Site para não perder o roteamento.
if (!leadOrigemBucket && hasGoogleTrackingSignal) leadOrigemBucket = 'google_ads';
if (!leadEntradaBucket && hasGoogleTrackingSignal) leadEntradaBucket = 'form_site';

const email = cleanText(pick(normalizedEvent.email, rawBody.email, rawCustomData.email));
const phone = cleanText(pick(normalizedEvent.phone, rawBody.phone, rawCustomData.phone));
const phoneRaw = cleanText(pick(normalizedEvent.phone_raw, rawBody.phone_raw, rawCustomData.phone_raw));

const value = eventCode === 'ganho'
  ? parseMoney(
      pick(
        normalizedEvent.valor_ganho,
        rawBody.valor_ganho,
        rawBody.value,
        rawBody.monetary_value,
        rawCustomData.valor_ganho,
        rawCustomData.value
      )
    )
  : null;

const formaGanho = cleanText(
  pick(
    normalizedEvent.forma_ganho,
    rawBody.forma_ganho,
    rawBody.forma_pagamento_ganho,
    rawBody.forma_pagamento,
    rawCustomData.forma_ganho,
    rawCustomData.forma_pagamento_ganho,
    rawCustomData.forma_pagamento
  )
);

const produtoServico = cleanText(
  pick(
    normalizedEvent.produto_servico,
    normalizedEvent.produto_serviço,
    normalizedEvent.produto_servico_ganho,
    normalizedEvent.produto_serviço_ganho,
    normalizedEvent['produto/serviço_ganho'],
    normalizedEvent['produto/servico_ganho'],

    rawBody.produto_servico,
    rawBody.produto_serviço,
    rawBody.produto_servico_ganho,
    rawBody.produto_serviço_ganho,
    rawBody['produto/serviço_ganho'],
    rawBody['produto/servico_ganho'],

    rawCustomData.produto_servico,
    rawCustomData.produto_serviço,
    rawCustomData.produto_servico_ganho,
    rawCustomData.produto_serviço_ganho,
    rawCustomData['produto/serviço_ganho'],
    rawCustomData['produto/servico_ganho'],

    // fallback legado
    normalizedEvent.procedimento_ganho,
    rawBody.procedimento_ganho,
    rawBody.procedimento_fechado,
    rawBody.procedimento,
    rawCustomData.procedimento_ganho,
    rawCustomData.procedimento_fechado,
    rawCustomData.procedimento
  )
);

const categoriaProdutoServico = cleanText(
  pick(
    normalizedEvent.categoria_produto_servico,
    normalizedEvent.categoria_produto_serviço,
    normalizedEvent.categoria_ganho,
    normalizedEvent.categoria,

    rawBody.categoria_produto_servico,
    rawBody.categoria_produto_serviço,
    rawBody.categoria_ganho,
    rawBody.categoria,

    rawCustomData.categoria_produto_servico,
    rawCustomData.categoria_produto_serviço,
    rawCustomData.categoria_ganho,
    rawCustomData.categoria
  )
);

const procedimentoGanho = cleanText(
  pick(
    normalizedEvent.procedimento_ganho,
    rawBody.procedimento_ganho,
    rawBody.procedimento_fechado,
    rawBody.procedimento,
    rawCustomData.procedimento_ganho,
    rawCustomData.procedimento_fechado,
    rawCustomData.procedimento,

    // fallback novo para compatibilidade
    produtoServico
  )
);

const normalizedEventId = pick(
  upsertedEvent.id,
  normalizedEvent.normalized_event_id
);

const rawEventId = pick(
  upsertedEvent.raw_event_id,
  normalizedEvent.raw_event_id
);

function basePayload(platform, route, platformEventName) {
  const eventId = [
    platform,
    route,
    normalizedEventId || rawEventId,
    eventCode
  ].filter(Boolean).join(':');

  return {
    event_id: eventId,
    event_code: eventCode,
    platform,
    platform_event_name: platformEventName,
    route,

    lead_entrada: leadEntrada,
    lead_entrada_bucket: leadEntradaBucket,
    lead_origem: leadOrigem,
    lead_origem_bucket: leadOrigemBucket,

    attribution: {
      ctwa_clid: ctwaClid,
      has_valid_ctwa_clid: hasValidCtwa,

      fbp: cleanText(pick(normalizedEvent.fbp, rawBody.fbp, rawCustomData.fbp)),
      fbc: cleanText(pick(normalizedEvent.fbc, rawBody.fbc, rawCustomData.fbc)),
      fbclid,

      gclid,
      gbraid,
      wbraid,

      google_campaign_id: googleCampaignId,
      google_adgroup_id: googleAdgroupId,
      google_ad_id: googleAdId,
      google_keyword: googleKeyword,

      conversion_source: cleanText(pick(normalizedEvent.conversion_source, rawBody.conversionSource, rawCustomData.conversionSource)),
      entry_point_conversion_source: cleanText(pick(normalizedEvent.entry_point_conversion_source, rawBody.entryPointConversionSource, rawCustomData.entryPointConversionSource)),
      entry_point_conversion_app: cleanText(pick(normalizedEvent.entry_point_conversion_app, rawBody.entryPointConversionApp, rawCustomData.entryPointConversionApp)),
      source_type: cleanText(pick(
        normalizedEvent.source_type,
        rawBody.sourceType,
        rawCustomData.sourceType,
        attributionSource.sourceType,
        attributionSource.source_type,
        attributionSource.type,
        lastAttributionSource.sourceType,
        lastAttributionSource.source_type,
        lastAttributionSource.type
      )),
      source_id: cleanText(pick(
        attributionSource.adId,
        attributionSource.ad_id,
        attributionSource.adID,
        lastAttributionSource.adId,
        lastAttributionSource.ad_id,
        lastAttributionSource.adID,
        normalizedEvent.source_id,
        rawBody.sourceId,
        rawCustomData.sourceId
      )),
      source_url: cleanText(pick(
        normalizedEvent.source_url,
        rawBody.sourceUrl,
        rawCustomData.sourceUrl,
        rawBody.source?.url,
        attributionSource.url,
        attributionSource.sourceUrl,
        attributionSource.source_url,
        lastAttributionSource.url,
        lastAttributionSource.sourceUrl,
        lastAttributionSource.source_url
      ))
    },

    user_data_source: {
      contact_id: cleanText(pick(normalizedEvent.contact_id, rawBody.contact_id, rawCustomData.contact_id)),
      phone,
      phone_raw: phoneRaw,
      email,
      first_name: cleanText(pick(normalizedEvent.first_name, rawBody.first_name, rawCustomData.first_name)),
      last_name: cleanText(pick(normalizedEvent.last_name, rawBody.last_name, rawCustomData.last_name)),
      full_name: cleanText(pick(normalizedEvent.full_name, rawBody.full_name, rawCustomData.full_name))
    },

    custom_data: {
      currency: 'BRL',
      value,

      produto_servico: produtoServico,
      categoria_produto_servico: categoriaProdutoServico,

      // legado: manter temporariamente para compatibilidade
      procedimento_ganho: procedimentoGanho || produtoServico,

      forma_ganho: formaGanho,
      client_id: cleanText(normalizedEvent.client_id),
      client_name: cleanText(normalizedEvent.client_name),
      ghl_location_id: cleanText(normalizedEvent.ghl_location_id),
      opportunity_id: cleanText(normalizedEvent.opportunity_id),
      pipeline_id: cleanText(normalizedEvent.pipeline_id),
      pipeline_name: cleanText(normalizedEvent.pipeline_name),
      pipeline_stage: cleanText(normalizedEvent.pipeline_stage),
      status: cleanText(normalizedEvent.status)
    }
  };
}

function makeJob({ platform, route, platformEventName, status = 'pending', lastError = null, payload }) {
  return {
    json: {
      routing_decision_status: 'job_created',
      routing_reason: lastError,
      should_create_outbox: true,
      should_create_conversion_outbox: true,

      normalized_event_id: normalizedEventId,
      raw_event_id: rawEventId,

      client_id: cleanText(normalizedEvent.client_id),
      client_name: cleanText(normalizedEvent.client_name),
      ghl_location_id: cleanText(normalizedEvent.ghl_location_id),
      contact_id: cleanText(pick(normalizedEvent.contact_id, rawBody.contact_id, rawCustomData.contact_id)),
      opportunity_id: cleanText(normalizedEvent.opportunity_id),

      event_code: eventCode,
      platform,
      route,

      // Campo legado da tabela conversion_outbox. Para Google, use como nome do evento da plataforma.
      meta_event_name: platformEventName,
      platform_event_name: platformEventName,

      status,
      last_error: lastError,
      payload: {
        ...payload,
        routing_checks: {
          allowed_event: allowedEvents.includes(eventCode),
          lead_entrada_received: leadEntrada,
          lead_entrada_bucket: leadEntradaBucket,
          lead_origem_received: leadOrigem,
          lead_origem_bucket: leadOrigemBucket,
          platform,
          route,
          platform_event_name: platformEventName,
          status,
          last_error: lastError
        }
      },

      outbox_status: status,
      outbox_last_error: lastError,
      outbox_payload: payload
    }
  };
}

function makeControlItem(reason, routingDecisionStatus = 'skipped') {
  return {
    json: {
      routing_decision_status: routingDecisionStatus,
      routing_reason: reason,
      should_create_outbox: false,
      should_create_conversion_outbox: false,
      normalized_event_id: normalizedEventId,
      raw_event_id: rawEventId,
      client_id: cleanText(normalizedEvent.client_id),
      client_name: cleanText(normalizedEvent.client_name),
      ghl_location_id: cleanText(normalizedEvent.ghl_location_id),
      contact_id: cleanText(pick(normalizedEvent.contact_id, rawBody.contact_id, rawCustomData.contact_id)),
      event_code: eventCode,
      platform: 'none',
      route: 'no_dispatch',
      meta_event_name: 'no_dispatch',
      platform_event_name: 'no_dispatch',
      status: 'skipped',
      last_error: reason,
      payload: {
        event_code: eventCode,
        platform: 'none',
        route: 'no_dispatch',
        lead_entrada: leadEntrada,
        lead_entrada_bucket: leadEntradaBucket,
        lead_origem: leadOrigem,
        lead_origem_bucket: leadOrigemBucket,
        routing_checks: {
          status: 'skipped',
          last_error: reason
        }
      }
    }
  };
}

const jobs = [];

if (allowedEvents.includes(eventCode) && leadOrigemBucket === 'facebook_ads') {
  const route = shouldUseWhatsappBusinessMessaging(
    {
      ...normalizedEvent,
      ctwa_clid: ctwaClid
    },
    leadEntradaBucket
  )
    ? 'whatsapp_bm'
    : 'standard';

  const metaEventName = getMetaEventName(eventCode, route);

  if (metaEventName) {
    let status = 'pending';
    let lastError = null;

    if (
      eventCode === 'lead' &&
      leadEntradaBucket === 'form_fbads' &&
      leadOrigemBucket === 'facebook_ads'
    ) {
      status = 'skipped';
      lastError = 'native_lead_form_lead_event_not_sent';
    }

    if (route === 'whatsapp_bm' && !hasValidCtwa) {
      status = 'skipped';
      lastError = 'missing_ctwa_clid_for_whatsapp_business_messaging';
    }

    const payload = basePayload('meta', route, metaEventName);
    payload.meta_event_name = metaEventName;
    payload.route = route;
    payload.attribution.is_whatsapp_route = route === 'whatsapp_bm';

    jobs.push(makeJob({
      platform: 'meta',
      route,
      platformEventName: metaEventName,
      status,
      lastError,
      payload
    }));
  }
}

if (allowedEvents.includes(eventCode) && leadOrigemBucket === 'google_ads' && leadEntradaBucket === 'form_site') {
  const googleEventName = getGoogleEventName(eventCode);

  if (googleEventName) {
    const hasClickId = Boolean(gclid || gbraid || wbraid);
    const hasUserIdentifier = Boolean(email || phone || phoneRaw);

    let status = 'pending';
    let lastError = null;

    if (!hasClickId && !hasUserIdentifier) {
      status = 'skipped';
      lastError = 'missing_google_match_key';
    }

    const payload = basePayload('google_ads', 'offline_conversion', googleEventName);

    payload.google_event_name = googleEventName;
    payload.google_event_code = eventCode;
    payload.route = 'offline_conversion';
    payload.click_ids = {
      gclid,
      gbraid,
      wbraid,
      has_click_id: hasClickId
    };
    payload.google_valuetrack = {
      google_campaign_id: googleCampaignId,
      google_adgroup_id: googleAdgroupId,
      google_ad_id: googleAdId,
      google_keyword: googleKeyword,
      has_google_campaign_id: Boolean(googleCampaignId),
      has_google_adgroup_id: Boolean(googleAdgroupId),
      has_google_ad_id: Boolean(googleAdId)
    };
    payload.match_keys = {
      has_click_id: hasClickId,
      has_user_identifier: hasUserIdentifier,
      has_email: Boolean(email),
      has_phone: Boolean(phone || phoneRaw)
    };

    // O workflow 04 deve resolver a conversion_action a partir de clients_base:
    // lead -> google_conversion_action_lead
    // agendado -> google_conversion_action_agendado
    // ganho -> google_conversion_action_ganho
    payload.google_config_hint = {
      expected_origin: 'google_ads',
      expected_entry: 'form_site',
      conversion_action_field: eventCode === 'lead'
        ? 'google_conversion_action_lead'
        : eventCode === 'agendado'
          ? 'google_conversion_action_agendado'
          : 'google_conversion_action_ganho'
    };

    jobs.push(makeJob({
      platform: 'google_ads',
      route: 'offline_conversion',
      platformEventName: googleEventName,
      status,
      lastError,
      payload
    }));
  }
}

if (jobs.length === 0) {
  if (!allowedEvents.includes(eventCode)) {
    return [makeControlItem(
      'event_code_not_sent_to_ad_platforms',
      'not_applicable'
    )];
  }

  return [makeControlItem(
    'no_eligible_tracking_route',
    'skipped'
  )];
}

return jobs;

const row = $json;

function cleanText(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text || null;
}

const conversionOutboxId = cleanText(row.conversion_outbox_id);
const outboxStatus = cleanText(row.outbox_status);
const platform = cleanText(row.platform);

const shouldDispatch = Boolean(conversionOutboxId && outboxStatus === 'pending');

return [
  {
    json: {
      raw_event_id: cleanText(row.raw_event_id),
      normalized_event_id: cleanText(row.normalized_event_id),
      conversion_outbox_id: conversionOutboxId,
      event_code: cleanText(row.event_code),
      platform,
      route: cleanText(row.route),
      platform_event_name: cleanText(row.meta_event_name),
      meta_event_name: platform === 'meta' ? cleanText(row.meta_event_name) : null,
      google_event_name: platform === 'google_ads' ? cleanText(row.meta_event_name) : null,
      outbox_status: outboxStatus,
      routing_decision_status: cleanText(row.routing_decision_status),
      routing_reason: cleanText(row.routing_reason || row.outbox_last_error),
      should_dispatch: shouldDispatch,
      should_dispatch_meta: Boolean(shouldDispatch && platform === 'meta'),
      should_dispatch_google: Boolean(shouldDispatch && platform === 'google_ads')
    }
  }
];
